/* My Little Money Home v5 — mobile-first, local-first, mixed-media Y2K scrapbook. */
const DAY=86400000;
const PAY_FREQ={weekly:52,biweekly:26,semimonthly:24,monthly:12};
const CATEGORIES=["Things for Me","Experiences","Home","Gifts","Giving & Causes","Hobby / Creative","Beauty","Travel","Other"];
const CLOTHES=["Tops","Bottoms","Dresses","Shoes","Bags","Outerwear","Accessories","Other"];
const ICONS={"Things for Me":"🎀","Experiences":"🎟️","Home":"🏡","Gifts":"🎁","Giving & Causes":"💞","Hobby / Creative":"🎨","Beauty":"🫧","Travel":"✈️","Other":"⭐"};
const GAME_MODES={classic:"CLASSIC",boost:"LITTLE BOOST",neglected:"NEGLECTED WISH",giving:"GIVING DAY",treat:"TREAT DAY",steady:"SLOW + STEADY"};
const BUILTIN_ACTIVITIES=[
  "go to the park","walk outside with a favorite playlist","go to the library","write for twenty minutes","paint something tiny","play a record front to back","burn incense and tidy one corner","light a candle and read","take care of your plants","have a jam session and clean","play dress up with clothes you own","make a pile of clothes to sell","eat fruit somewhere sunny","make a vegetable snack","walk a trail or walking path","climb at a free/public spot if available","take photos of interesting textures","make a collage from old magazines","rearrange a shelf","learn one dance from a video","call a friend and walk together","watch the sunset","visit a free museum day","draw your dream room","make a playlist for a future trip","do a no-spend picnic with food you already have","style three outfits from your closet","write postcards you already own","make tea and sit outside","practice a hobby you forgot you had"
];
const WHO=["solo date","with a friend","with family","invite someone you miss","just you + your headphones"];
const WHERE=["outside","at home","at a park","at the library","somewhere you can walk","on the floor with a blanket","by a window","in your neighborhood"];
const WHEN=["after work","this morning","this afternoon","tonight","this weekend","when you feel like shopping","the next free hour"];

const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const uid=()=>Math.random().toString(36).slice(2,8)+Date.now().toString(36);
const num=v=>Number(v||0), clamp=(v,a,b)=>Math.min(b,Math.max(a,v));
const todayISO=()=>new Date().toISOString().slice(0,10);
const money=v=>new Intl.NumberFormat("en-US",{style:"currency",currency:"USD"}).format(num(v));
const fmtDate=d=>d?new Date(`${String(d).slice(0,10)}T12:00:00`).toLocaleDateString("en-US",{month:"short",day:"numeric",year:"numeric"}):"—";
const esc=s=>String(s??"").replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"}[m]));
const attr=s=>esc(s).replace(/`/g,"&#096;");
const deep=o=>JSON.parse(JSON.stringify(o));
const daysAgo=d=>Math.max(0,Math.floor((Date.now()-new Date(`${d}T12:00:00`).getTime())/DAY));
const addDays=(d,n)=>{const x=new Date(`${d}T12:00:00`);x.setDate(x.getDate()+num(n));return x.toISOString().slice(0,10)};
const diffDays=(a,b)=>Math.ceil((new Date(`${b}T12:00:00`)-new Date(`${a}T12:00:00`))/DAY);
const monthKey=d=>String(d||todayISO()).slice(0,7);

const DEFAULT_STATE={
  version:5,
  settings:{payFrequency:"biweekly",savePct:30,funPct:20,defaultWaitDays:30,sound:false,sparkle:true,coolLow:2,coolMid:5,coolHigh:10,coolLuxury:21,roomBackgrounds:{},roomPatterns:{}},
  paychecks:[],costs:[],sinkingFunds:[],savingsGoals:[],savingsContribs:[],sinkingContribs:[],
  wishes:[],rolls:[],impulses:[],memories:[],
  notebooks:[{id:"starterbook",title:"my little rules",body:"",color:"pink"}],
  owned:[],outfits:[],bags:[],adventures:[],customActivities:[],
  game:{mode:"classic",lastWishId:null,session:"tiny roll"}
};

function migrateV4(v){
  const s=deep(DEFAULT_STATE); if(!v)return s;
  s.settings={...s.settings,...(v.settings||{}),roomBackgrounds:{}};
  ["paychecks","costs","sinkingFunds","savingsGoals","savingsContribs","sinkingContribs","wishes","rolls","impulses","memories"].forEach(k=>s[k]=Array.isArray(v[k])?v[k]:[]);
  s.notebooks=(v.notes||[]).length?(v.notes||[]).map(n=>({id:n.id||uid(),title:n.title||"note",body:n.body||n.text||"",color:n.color||"yellow"})):s.notebooks;
  s.game={...s.game,...(v.game||{})};
  s.version=5; return normalize(s);
}
function normalize(s){
  const b=deep(DEFAULT_STATE);s={...b,...(s||{}),settings:{...b.settings,...(s?.settings||{}),roomBackgrounds:{...(s?.settings?.roomBackgrounds||{})}},game:{...b.game,...(s?.game||{})}};
  ["paychecks","costs","sinkingFunds","savingsGoals","savingsContribs","sinkingContribs","wishes","rolls","impulses","memories","notebooks","owned","outfits","bags","adventures","customActivities"].forEach(k=>{if(!Array.isArray(s[k]))s[k]=[]});
  s.wishes=s.wishes.map(w=>({...w,id:w.id||uid(),price:num(w.price),baseSaved:num(w.baseSaved??w.saved),waitDays:num(w.waitDays||30),status:w.status||"waiting",mediaKey:w.mediaKey||""}));
  s.savingsGoals=s.savingsGoals.map(g=>({...g,id:g.id||uid(),target:num(g.target),baseSaved:num(g.baseSaved??g.saved),mediaKey:g.mediaKey||"",type:g.type||"Long Term"}));
  s.owned=s.owned.map(o=>({...o,id:o.id||uid(),mediaKey:o.mediaKey||""}));
  return s;
}
function loadState(){
  try{const v5=localStorage.getItem("littleMoneyHomeV5");if(v5)return normalize(JSON.parse(v5));const v4=localStorage.getItem("littleMoneyHomeV4");if(v4){const x=migrateV4(JSON.parse(v4));localStorage.setItem("littleMoneyHomeV5",JSON.stringify(x));return x}}
  catch(e){console.warn(e)} return deep(DEFAULT_STATE)
}
function saveState(){try{localStorage.setItem("littleMoneyHomeV5",JSON.stringify(state))}catch(e){toast("storage is full — export a backup ♡")}}
let state=loadState(),route="home",currentRoll=null,selectedOutfit=new Set(),selectedBag=new Set(),activeNotebook=state.notebooks[0]?.id||null,adventureRoll=null;

/* ---------- IndexedDB media ---------- */
const Media={
  db:null,urls:new Map(),
  async open(){if(this.db)return this.db;this.db=await new Promise((res,rej)=>{const q=indexedDB.open("moneyhomeMediaV1",1);q.onupgradeneeded=()=>q.result.createObjectStore("media");q.onsuccess=()=>res(q.result);q.onerror=()=>rej(q.error)});return this.db},
  async put(blob,key=uid()){const db=await this.open();await new Promise((res,rej)=>{const tx=db.transaction("media","readwrite");tx.objectStore("media").put(blob,key);tx.oncomplete=res;tx.onerror=()=>rej(tx.error)});return key},
  async get(key){if(!key)return null;const db=await this.open();return await new Promise((res,rej)=>{const q=db.transaction("media").objectStore("media").get(key);q.onsuccess=()=>res(q.result||null);q.onerror=()=>rej(q.error)})},
  async url(key){if(!key)return "";if(this.urls.has(key))return this.urls.get(key);const b=await this.get(key);if(!b)return "";const u=URL.createObjectURL(b);this.urls.set(key,u);return u},
  async del(key){if(!key)return;const db=await this.open();await new Promise((res,rej)=>{const tx=db.transaction("media","readwrite");tx.objectStore("media").delete(key);tx.oncomplete=res;tx.onerror=()=>rej(tx.error)});if(this.urls.has(key)){URL.revokeObjectURL(this.urls.get(key));this.urls.delete(key)}},
  async keys(){const db=await this.open();return await new Promise((res,rej)=>{const q=db.transaction("media").objectStore("media").getAllKeys();q.onsuccess=()=>res(q.result);q.onerror=()=>rej(q.error)})}
};
async function shrinkImage(file){
  if(file.type==="image/gif")return file;
  try{const bmp=await createImageBitmap(file);const max=1400,scale=Math.min(1,max/Math.max(bmp.width,bmp.height));const c=document.createElement("canvas");c.width=Math.round(bmp.width*scale);c.height=Math.round(bmp.height*scale);c.getContext("2d").drawImage(bmp,0,0,c.width,c.height);return await new Promise(r=>c.toBlob(b=>r(b||file),"image/webp",.84))}catch(e){return file}
}
async function saveUpload(file,oldKey=""){if(!file)return oldKey;const blob=await shrinkImage(file);const key=await Media.put(blob);if(oldKey&&oldKey!==key)await Media.del(oldKey);return key}
async function hydrateMedia(root=document){
  const nodes=$$("[data-media]",root);await Promise.all(nodes.map(async n=>{const u=await Media.url(n.dataset.media);if(!u)return;if(n.tagName==="IMG")n.src=u;else n.style.backgroundImage=`url(${u})`}));
  const bg=state.settings.roomBackgrounds[ROUTE_ROOM[route]||route];if(bg){const u=await Media.url(bg);$("#roomBackdrop").style.backgroundImage=u?`url(${u})`:""}else $("#roomBackdrop").style.backgroundImage="";
}
function mediaImg(key,cls="",alt=""){return key?`<img class="${cls}" data-media="${key}" alt="${attr(alt)}">`:""}

/* ---------- money logic ---------- */
function annualCost(c){const a=num(c.amount);return c.frequency==="weekly"?a*52:c.frequency==="quarterly"?a*4:c.frequency==="annual"?a:a*12}
function protectedPerPay(){return state.costs.reduce((t,c)=>t+annualCost(c),0)/(PAY_FREQ[state.settings.payFrequency]||26)}
function sinkingCurrent(f){return num(f.baseSaved)+state.sinkingContribs.filter(c=>c.fundId===f.id).reduce((a,c)=>a+num(c.amount),0)}
function goalCurrent(g){return num(g.baseSaved)+state.savingsContribs.filter(c=>c.goalId===g.id).reduce((a,c)=>a+num(c.amount),0)}
function sinkingRecommendation(f){if(!f.dueDate)return 0;const rem=Math.max(0,num(f.target)-sinkingCurrent(f));if(!rem)return 0;const days=Math.max(1,diffDays(todayISO(),f.dueDate));const pays=Math.max(1,Math.ceil(days/365*(PAY_FREQ[state.settings.payFrequency]||26)));return rem/pays}
function planIncome(amount){amount=num(amount);const protectedAmt=protectedPerPay(),sinking=state.sinkingFunds.reduce((t,f)=>t+sinkingRecommendation(f),0),left=Math.max(0,amount-protectedAmt-sinking),save=left*state.settings.savePct/100,fun=left*state.settings.funPct/100,free=Math.max(0,left-save-fun);return {protected:protectedAmt,sinking,leftover:left,savings:save,fun,free}}
function latestPay(){return [...state.paychecks].sort((a,b)=>String(b.date).localeCompare(String(a.date)))[0]||null}
function wishSaved(w){return num(w.baseSaved)+state.rolls.filter(r=>r.wishId===w.id).reduce((a,r)=>a+num(r.amount),0)}
function funIn(){return state.paychecks.reduce((a,p)=>a+num(p.snapshot?.fun),0)}
function impulseOut(){return state.impulses.filter(x=>x.deductFun&&!x.returned).reduce((a,x)=>a+num(x.amount),0)}
function funJar(){return funIn()-state.rolls.reduce((a,r)=>a+num(r.amount),0)-impulseOut()}
function progressVal(saved,target){return target?clamp(Math.round(num(saved)/num(target)*100),0,100):0}
function coolDays(price){price=num(price);return price>=1000?state.settings.coolLuxury:price>=300?state.settings.coolHigh:price>=100?state.settings.coolMid:state.settings.coolLow}
function syncWishes(){state.wishes.forEach(w=>{const sv=wishSaved(w);if(w.status==="active"&&sv>=w.price){w.status="ready";w.fundedDate=w.fundedDate||todayISO();w.coolOffDays=w.coolOffDays??coolDays(w.price)}if(w.status==="ready"&&sv<w.price){w.status="active";delete w.fundedDate}})}
function coolLeft(w){return w.fundedDate?Math.max(0,diffDays(todayISO(),addDays(w.fundedDate,w.coolOffDays||coolDays(w.price)))):0}
function activeWishes(){syncWishes();return state.wishes.filter(w=>w.status==="active"&&wishSaved(w)<w.price)}
function readyWishes(){syncWishes();return state.wishes.filter(w=>w.status==="ready")}
function eligible(w){return daysAgo(w.dateAdded)>=num(w.waitDays||30)}
function thoughtfulness(w){return clamp(Math.min(35,Math.round(daysAgo(w.dateAdded)/Math.max(1,w.waitDays)*35))+num(w.research||0)*7+(w.why?12:0)+(w.betterChecked?12:0)-(w.ownsSimilar?8:0),0,100)}
function applyPaycheckPlan(p){
  if(p.planApplied)return;const snap=p.snapshot||planIncome(p.amount);p.snapshot=snap;p.planApplied=true;
  const goals=state.savingsGoals.filter(g=>goalCurrent(g)<g.target);if(goals.length&&snap.savings>0){const main=goals.find(g=>g.priority==="Main Quest")||goals[0];state.savingsContribs.push({id:uid(),goalId:main.id,paycheckId:p.id,date:p.date,amount:snap.savings})}
  const recs=state.sinkingFunds.map(f=>[f,sinkingRecommendation(f)]).filter(x=>x[1]>0);const total=recs.reduce((a,x)=>a+x[1],0);if(total>0&&snap.sinking>0)recs.forEach(([f,r])=>state.sinkingContribs.push({id:uid(),fundId:f.id,paycheckId:p.id,date:p.date,amount:snap.sinking*(r/total)}));
}

/* ---------- ui helpers ---------- */
const PRIMARY=[["home","🏠","HOME"],["goals","🌱","GOALS"],["wish","📌","WISH"],["play","🎲","PLAY"],["me","💿","ME"]];
const ROUTE_ROOM={home:"home",goals:"goals",wish:"wish",waiting:"wish",envelopes:"wish",ready:"wish",play:"casino",dice:"casino",owned:"owned",closet:"closet",bag:"bag",adventure:"adventure",notebooks:"notes",oops:"oops",money:"money",memory:"memory",settings:"settings",me:"home"};
function primaryFor(r){if(["goals","money"].includes(r))return "goals";if(["wish","waiting","envelopes","ready"].includes(r))return "wish";if(["play","dice","closet","bag","adventure"].includes(r))return "play";if(["me","owned","notebooks","oops","memory","settings"].includes(r))return "me";return "home"}
function renderNav(){const active=primaryFor(route);$("#bottomNav").innerHTML=PRIMARY.map(([id,ic,l])=>`<button class="navbtn ${active===id?"active":""}" data-route="${id}"><i>${ic}</i><span>${l}</span></button>`).join("");$$('[data-route]',$("#bottomNav")).forEach(b=>b.onclick=()=>go(b.dataset.route))}
function go(r){route=r;currentRoll=null;window.scrollTo({top:0,behavior:"instant"});render()}
function setRoom(){const room=ROUTE_ROOM[route]||"home";$("#main").className=`main room-${room}`}
function head(title,add="",mini=""){return `<div class="page-head"><h1 class="page-title">${mini?`<small>${mini}</small>`:""}${title}</h1>${add}</div>`}
function section(title,action=""){return `<div class="section-row"><h2 class="section-label">${title}</h2>${action}</div>`}
function empty(icon,text){return `<div class="empty"><div style="font-size:34px;margin-bottom:6px">${icon}</div>${text}</div>`}
function pctBar(v){return `<div class="progress"><i style="width:${clamp(v,0,100)}%"></i></div>`}
function toast(t){const el=$("#toast");el.textContent=t;el.classList.add("show");setTimeout(()=>el.classList.remove("show"),1700)}
function celebrate(){for(let i=0;i<20;i++){const s=document.createElement("span");s.textContent=["♡","✦","★","💿","🎀"][i%5];s.style.left=Math.random()*100+"%";s.style.animationDelay=Math.random()*.25+"s";$("#confetti").appendChild(s);setTimeout(()=>s.remove(),1800)}}
function modal(title,html,onSave=null,saveLabel="save ♡"){$("#modalTitle").textContent=title;$("#modalBody").innerHTML=html;$("#modalSave").textContent=saveLabel;$("#modalSave").style.display=onSave?"inline-block":"none";$("#modalActions .ghost").textContent=onSave?"cancel":"close";$("#modalSave").onclick=async e=>{e.preventDefault();const ok=await onSave?.();if(ok!==false)$("#modal").close()};$("#modal").showModal();hydrateMedia($("#modal"))}
function confirmDelete(label,fn){if(confirm(`Delete ${label}?`)){fn();saveState();render();toast("deleted ♡")}}
function uploadField(key="",label="photo / gif"){return `<div class="field full"><label>${label}</label><div class="upload-box">${key?mediaImg(key,"upload-preview","preview"):`<div style="font-size:34px">📸</div>`}<input id="fMedia" type="file" accept="image/*,.gif"><div class="tiny">photos, transparent stickers + GIFs stay on this device</div></div></div>`}

/* ---------- media cards ---------- */
function goalCard(g){const cur=goalCurrent(g),p=progressVal(cur,g.target);return `<article class="goal-card"><div class="goal-media">${g.mediaKey?mediaImg(g.mediaKey,"",g.name):`<div class="media-placeholder">${g.type==="Long Term"?"🏡":"🌱"}</div>`}</div><div class="goal-actions"><button class="glass edit-goal" data-id="${g.id}">✎</button><button class="glass del-goal" data-id="${g.id}">×</button></div><div class="goal-copy"><div class="goal-title">${esc(g.name)}</div><div class="moneyline">${money(cur)} / ${money(g.target)}</div>${pctBar(p)}<div class="tiny" style="margin-top:4px">${p}% · ${esc(g.priority||"Goal")}</div></div></article>`}
function pinCard(w){const sv=wishSaved(w),p=progressVal(sv,w.price);return `<article class="pin"><div>${w.mediaKey?mediaImg(w.mediaKey,"",w.name):`<div class="pin-placeholder">${ICONS[w.category]||"♡"}</div>`}</div><div class="pin-actions"><button class="glass edit-wish" data-id="${w.id}">✎</button><button class="glass del-wish" data-id="${w.id}">×</button></div><div class="pin-info"><div class="pin-title">${esc(w.name)}</div><div class="pin-price">${money(w.price)}</div>${w.status==="active"||w.status==="ready"?pctBar(p):""}<div class="tiny-meta"><span class="chip pink">${w.status==="waiting"?(eligible(w)?"READY TO ENVELOPE":`${daysAgo(w.dateAdded)}/${w.waitDays} DAYS`):w.status.toUpperCase()}</span></div></div></article>`}
function ownedCard(o,clickClass=""){return `<article class="owned-card ${clickClass}" data-id="${o.id}">${o.mediaKey?mediaImg(o.mediaKey,"",o.name):`<div class="owned-sticker">${o.category==="Bags"?"👜":"👚"}</div>`}<button class="icon-delete del-owned" data-id="${o.id}">×</button><div class="owned-name">${esc(o.name)}</div><div class="heartline">${"♡".repeat(clamp(num(o.love||5),1,5))}</div></article>`}

/* ---------- home ---------- */
function renderHome(){
  const goals=state.savingsGoals.filter(g=>g.type==="Long Term"||g.priority==="Main Quest");const inspo=state.wishes.filter(w=>["waiting","active","ready"].includes(w.status));const loves=state.owned.slice().sort((a,b)=>num(b.love)-num(a.love));const jar=funJar();
  $("#view").innerHTML=head("money home",`<button class="btn hot" id="homeAdd">＋</button>`,`♡ LOCAL LITTLE WORLD`)+
  section("LONG-TERM GOALS",`<button class="btn mini yellow" id="newGoalHome">+ GOAL</button>`)+
  (goals.length?`<div class="scroll-x">${goals.map(goalCard).join("")}</div>`:empty("🏡","add a future you can see — a house, trip, treatment, anything"))+
  section("WISH INSPO",`<button class="btn mini hot" id="newWishHome">+ PIN</button>`)+
  (inspo.length?`<div class="scroll-x">${inspo.slice(0,12).map(w=>`<div style="width:150px">${pinCard(w)}</div>`).join("")}</div>`:empty("📌","pin something you want to think about, not buy today"))+
  section("I ALREADY LOVE",`<button class="btn mini aqua" id="newOwnedHome">+ LOVE</button>`)+
  (loves.length?`<div class="scroll-x">${loves.slice(0,14).map(ownedCard).join("")}</div>`:empty("💗","build a feed of things you already own and love"))+
  section("FUN MONEY")+`<div class="jar-mini"><div><div class="tiny">AVAILABLE NOW</div><strong>${money(jar)}</strong><div class="tiny">oops buys can honestly subtract from this</div></div><div class="jar-art" style="--fill:${jar>0?65:4}%">♡</div></div>`+
  `<div class="menu-grid" style="margin-top:12px"><button class="menu-card" data-go="notebooks"><i>📝</i>notebooks</button><button class="menu-card" data-go="closet"><i>👗</i>closet</button><button class="menu-card" data-go="adventure"><i>🌳</i>free day</button><button class="menu-card" data-go="oops"><i>🛍️</i>oops</button><button class="menu-card" data-go="dice"><i>🎲</i>roll</button><button class="menu-card" data-go="money"><i>💵</i>money</button></div>`;
  bindCommon();$("#homeAdd").onclick=()=>quickAdd();$("#newGoalHome").onclick=()=>goalModal();$("#newWishHome").onclick=()=>wishModal();$("#newOwnedHome").onclick=()=>ownedModal();$$('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));
}

/* ---------- goals + money ---------- */
function renderGoals(){
  const long=state.savingsGoals.filter(g=>g.type==="Long Term"),other=state.savingsGoals.filter(g=>g.type!=="Long Term");
  $("#view").innerHTML=head("goals",`<button class="btn hot" id="addGoal">+ GOAL</button>`,`MAKE THE FUTURE VISIBLE`)+section("BIG LIFE STUFF")+(long.length?`<div class="scroll-x">${long.map(goalCard).join("")}</div>`:empty("🏠","add a long-term goal + a picture that makes you want it"))+section("OTHER GOALS")+(other.length?`<div class="scroll-x">${other.map(goalCard).join("")}</div>`:empty("🌱","small goals can live here too"))+`<button class="btn aqua" style="width:100%;margin-top:14px" id="moneyPlan">OPEN MONEY PLAN 💵</button>`;
  $("#addGoal").onclick=()=>goalModal();$("#moneyPlan").onclick=()=>go("money");bindCommon();
}
function goalModal(g=null){
  const x=g||{name:"",target:"",baseSaved:0,type:"Long Term",priority:"Main Quest",mediaKey:""};
  modal(g?"edit goal":"new goal",`<div class="form-grid"><div class="field full"><label>goal</label><input id="fName" value="${attr(x.name)}" placeholder="down payment / dream trip / keratin treatment"></div><div class="field"><label>target</label><input id="fTarget" type="number" min="0" step=".01" value="${x.target}"></div><div class="field"><label>saved already</label><input id="fSaved" type="number" min="0" step=".01" value="${x.baseSaved||0}"></div><div class="field"><label>kind</label><select id="fType"><option ${x.type==="Long Term"?"selected":""}>Long Term</option><option ${x.type==="Short Term"?"selected":""}>Short Term</option></select></div><div class="field"><label>priority</label><select id="fPriority"><option ${x.priority==="Main Quest"?"selected":""}>Main Quest</option><option ${x.priority==="Protected"?"selected":""}>Protected</option><option ${x.priority==="Side Quest"?"selected":""}>Side Quest</option></select></div>${uploadField(x.mediaKey,"inspo photo / gif")}</div>`,async()=>{const name=$("#fName").value.trim(),target=num($("#fTarget").value);if(!name||target<=0){toast("name + target first ♡");return false}const mediaKey=await saveUpload($("#fMedia").files[0],x.mediaKey);const data={name,target,baseSaved:num($("#fSaved").value),type:$("#fType").value,priority:$("#fPriority").value,mediaKey};if(g)Object.assign(g,data);else state.savingsGoals.push({id:uid(),...data});saveState();render();toast("goal saved ✦")})
}
function renderMoney(){
  const pay=latestPay();const plan=pay?.snapshot||null;
  $("#view").innerHTML=head("money plan",`<button class="btn hot" id="addPay">+ PAYCHECK</button>`,`REAL NUMBERS ONLY`)+
  `<div class="window"><div class="winbar"><b>money_split.exe</b><span>♡</span></div><div class="window-body"><div class="form-grid"><div class="field"><label>save % of leftover</label><input id="savePct" type="number" min="0" max="100" value="${state.settings.savePct}"></div><div class="field"><label>fun % of leftover</label><input id="funPct" type="number" min="0" max="100" value="${state.settings.funPct}"></div></div><button class="btn lime" id="saveRules" style="margin-top:8px">SAVE RULES</button></div></div>`+
  section("LATEST PAYDAY")+(pay?`<div class="list"><div class="list-item"><div class="list-thumb">💵</div><div class="list-copy"><b>${money(pay.amount)}</b><small>${fmtDate(pay.date)}</small></div><div class="list-actions"><button class="btn mini red del-pay" data-id="${pay.id}">DELETE</button></div></div></div><div class="window" style="margin-top:8px"><div class="window-body"><div class="casino-hud" style="color:inherit"><div class="hud" style="background:#e8ffd9;color:#355"><span>NEEDS</span><b style="color:#234">${money(plan.protected+plan.sinking)}</b></div><div class="hud" style="background:#ffd9ef;color:#624"><span>SAVE</span><b style="color:#523">${money(plan.savings)}</b></div><div class="hud" style="background:#d9ffff;color:#355"><span>FUN</span><b style="color:#234">${money(plan.fun)}</b></div></div></div></div>`:empty("💵","add your actual take-home paycheck — there are no demo numbers"))+
  section("BILLS",`<button class="btn mini aqua" id="addCost">+ BILL</button>`)+(state.costs.length?`<div class="list">${state.costs.map(c=>`<div class="list-item"><div class="list-thumb">🏡</div><div class="list-copy"><b>${esc(c.name)}</b><small>${money(c.amount)} · ${c.frequency}</small></div><div class="list-actions"><button class="btn mini red del-cost" data-id="${c.id}">DELETE</button></div></div>`).join("")}</div>`:empty("🏡","add rent + important expenses"))+
  section("SINKING FUNDS",`<button class="btn mini yellow" id="addSink">+ FUND</button>`)+(state.sinkingFunds.length?`<div class="list">${state.sinkingFunds.map(f=>`<div class="list-item"><div class="list-thumb">🧃</div><div class="list-copy"><b>${esc(f.name)}</b><small>${money(sinkingCurrent(f))} / ${money(f.target)} · ${f.dueDate?money(sinkingRecommendation(f))+" each payday":"no date"}</small></div><div class="list-actions"><button class="btn mini red del-sink" data-id="${f.id}">DELETE</button></div></div>`).join("")}</div>`:empty("🧃","car maintenance, gifts, annual bills — things that sneak up on you"));
  $("#saveRules").onclick=()=>{state.settings.savePct=clamp(num($("#savePct").value),0,100);state.settings.funPct=clamp(num($("#funPct").value),0,100);saveState();toast("rules saved ♡")};$("#addPay").onclick=()=>payModal();$("#addCost").onclick=()=>costModal();$("#addSink").onclick=()=>sinkModal();
  $$(".del-pay").forEach(b=>b.onclick=()=>confirmDelete("paycheck",()=>{state.paychecks=state.paychecks.filter(p=>p.id!==b.dataset.id);state.savingsContribs=state.savingsContribs.filter(c=>c.paycheckId!==b.dataset.id);state.sinkingContribs=state.sinkingContribs.filter(c=>c.paycheckId!==b.dataset.id)}));$$(".del-cost").forEach(b=>b.onclick=()=>confirmDelete("bill",()=>state.costs=state.costs.filter(c=>c.id!==b.dataset.id)));$$(".del-sink").forEach(b=>b.onclick=()=>confirmDelete("fund",()=>{state.sinkingFunds=state.sinkingFunds.filter(f=>f.id!==b.dataset.id);state.sinkingContribs=state.sinkingContribs.filter(c=>c.fundId!==b.dataset.id)}));
}
function payModal(){modal("add paycheck",`<div class="form-grid"><div class="field"><label>date</label><input id="fDate" type="date" value="${todayISO()}"></div><div class="field"><label>take-home amount</label><input id="fAmount" type="number" min="0" step=".01" autofocus></div></div>`,()=>{const amount=num($("#fAmount").value);if(amount<=0){toast("add your real amount ♡");return false}const p={id:uid(),date:$("#fDate").value,amount,snapshot:planIncome(amount),planApplied:false};state.paychecks.push(p);applyPaycheckPlan(p);saveState();render();toast("payday logged 💵")})}
function costModal(){modal("add bill",`<div class="form-grid"><div class="field full"><label>bill / important expense</label><input id="fName"></div><div class="field"><label>amount</label><input id="fAmount" type="number" min="0" step=".01"></div><div class="field"><label>frequency</label><select id="fFreq"><option>monthly</option><option>weekly</option><option>quarterly</option><option>annual</option></select></div></div>`,()=>{const name=$("#fName").value.trim(),amount=num($("#fAmount").value);if(!name||amount<=0)return false;state.costs.push({id:uid(),name,amount,frequency:$("#fFreq").value});saveState();render()})}
function sinkModal(){modal("new sinking fund",`<div class="form-grid"><div class="field full"><label>what for?</label><input id="fName"></div><div class="field"><label>target</label><input id="fTarget" type="number" min="0"></div><div class="field"><label>saved already</label><input id="fSaved" type="number" min="0" value="0"></div><div class="field full"><label>need it by</label><input id="fDate" type="date"></div></div>`,()=>{const name=$("#fName").value.trim(),target=num($("#fTarget").value);if(!name||target<=0)return false;state.sinkingFunds.push({id:uid(),name,target,baseSaved:num($("#fSaved").value),dueDate:$("#fDate").value});saveState();render()})}

