function renderPlay(){$("#view").innerHTML=head("play",``,`SHOP YOUR LIFE / GO DO SOMETHING`)+`<div class="menu-grid"><button class="menu-card" data-go="dice"><i>🎲</i>fun money roll</button><button class="menu-card" data-go="closet"><i>👗</i>dress up</button><button class="menu-card" data-go="bag"><i>👜</i>what's in my bag</button><button class="menu-card" data-go="adventure"><i>🌳</i>free adventure</button></div>`+section("I ALREADY LOVE")+(state.owned.length?`<div class="scroll-x">${state.owned.slice(0,16).map(ownedCard).join("")}</div>`:empty("💗","add things you already own so this tab gives you something else to scroll"));$$('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));bindCommon()}
function chooseRoll(pool){if(!pool.length)return null;let arr=[...pool];if(state.game.mode==="giving")arr=arr.filter(w=>w.category==="Giving & Causes");if(state.game.mode==="treat")arr=arr.filter(w=>["Things for Me","Experiences","Beauty"].includes(w.category));if(!arr.length)arr=pool;if(state.game.mode==="steady"&&state.game.lastWishId&&arr.length>1)arr=arr.filter(w=>w.id!==state.game.lastWishId);if(state.game.mode==="neglected")arr.sort((a,b)=>(a.lastFunded||a.dateAdded).localeCompare(b.lastFunded||b.dateAdded));if(state.game.mode==="neglected")return arr[0];if(state.game.mode==="boost"){const weighted=[];arr.forEach(w=>{const p=progressVal(wishSaved(w),w.price);for(let i=0;i<1+Math.floor(p/25);i++)weighted.push(w)});arr=weighted}return arr[Math.floor(Math.random()*arr.length)]}
function renderDice(){const pool=activeWishes(),jar=funJar();$("#view").innerHTML=head("tiny casino",`<button class="btn yellow" id="modeBtn">${GAME_MODES[state.game.mode]}</button>`,`NO REAL GAMBLING · JUST YOUR ENVELOPES`)+`<div class="casino-hud"><div class="hud">JAR<b>${money(jar)}</b></div><div class="hud">ENVELOPES<b>${pool.length}</b></div><div class="hud">DEPOSIT<b id="depLabel">$1</b></div></div><div class="casino-table"><div class="dice-big">🎲</div>${currentRoll?`<div class="roll-card">${currentRoll.mediaKey?mediaImg(currentRoll.mediaKey,"",currentRoll.name):`<div class="media-placeholder">💌</div>`}<b>${esc(currentRoll.name)}</b><small>${money(wishSaved(currentRoll))} / ${money(currentRoll.price)}</small></div>`:`<div style="font:900 22px 'Trebuchet MS';margin:34px 0 20px">PICK AN ENVELOPE<br>AT RANDOM</div>`}<div class="casino-actions"><select id="deposit" class="btn"><option value="1">$1</option><option value="2">$2</option><option value="5">$5</option><option value="10">$10</option></select><button class="btn hot" id="rollBtn" ${!pool.length||jar<=0?"disabled":""}>ROLL ✦</button>${currentRoll?`<button class="btn lime" id="fundBtn">GIVE IT ♡</button><button class="btn aqua" id="rerouteBtn">REROLL</button>`:""}</div></div>`+section("RECENT")+(state.rolls.length?`<div class="list">${state.rolls.slice(-6).reverse().map(r=>`<div class="list-item"><div class="list-thumb">🎲</div><div class="list-copy"><b>${esc(r.wishName)}</b><small>${fmtDate(r.date)}</small></div><div class="list-actions"><b>${money(r.amount)}</b><button class="btn mini red del-roll" data-id="${r.id}">UNDO</button></div></div>`).join("")}</div>`:empty("🎲","no rolls yet"));$("#rollBtn")?.addEventListener("click",()=>{currentRoll=chooseRoll(pool);if(currentRoll){state.game.lastWishId=currentRoll.id;saveState();renderDice()}});$("#deposit")?.addEventListener("change",e=>$("#depLabel").textContent=money(e.target.value));$("#fundBtn")?.addEventListener("click",()=>{const amt=Math.min(num($("#deposit").value),Math.max(0,funJar()));if(!currentRoll||amt<=0)return;state.rolls.push({id:uid(),wishId:currentRoll.id,wishName:currentRoll.name,date:todayISO(),amount:amt});currentRoll.lastFunded=todayISO();currentRoll=null;syncWishes();saveState();render();celebrate();toast("tiny dollar delivered ♡")});$("#rerouteBtn")?.addEventListener("click",()=>{currentRoll=chooseRoll(pool.filter(w=>w.id!==currentRoll?.id));renderDice()});$("#modeBtn").onclick=()=>modeModal();$$('.del-roll').forEach(b=>b.onclick=()=>confirmDelete("deposit",()=>state.rolls=state.rolls.filter(r=>r.id!==b.dataset.id)));hydrateMedia()}
function modeModal(){modal("game mode",`<div class="menu-grid">${Object.entries(GAME_MODES).map(([k,v])=>`<button type="button" class="menu-card choose-mode" data-mode="${k}"><i>${k==="giving"?"💞":k==="treat"?"🎀":"🎲"}</i>${v}</button>`).join("")}</div>`,null);$$('.choose-mode').forEach(b=>b.onclick=()=>{state.game.mode=b.dataset.mode;saveState();$("#modal").close();render()})}

