function quickAdd(){modal("quick add",`<div class="menu-grid"><button type="button" class="menu-card q" data-q="goal"><i>🌱</i>goal</button><button type="button" class="menu-card q" data-q="wish"><i>📌</i>wish</button><button type="button" class="menu-card q" data-q="owned"><i>💗</i>already mine</button><button type="button" class="menu-card q" data-q="oops"><i>🛍️</i>oops</button><button type="button" class="menu-card q" data-q="pay"><i>💵</i>paycheck</button><button type="button" class="menu-card q" data-q="book"><i>📝</i>notebook</button></div>`,null);$$('.q').forEach(b=>b.onclick=()=>{$("#modal").close();({goal:goalModal,wish:wishModal,owned:ownedModal,oops:oopsModal,pay:payModal,book:()=>go("notebooks")}[b.dataset.q])()})}
async function blobToDataURL(blob){return await new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(blob)})}
function dataURLToBlob(data){const [meta,b64]=data.split(',');const mime=meta.match(/data:(.*?);/)?.[1]||'application/octet-stream';const bytes=atob(b64);const arr=new Uint8Array(bytes.length);for(let i=0;i<bytes.length;i++)arr[i]=bytes.charCodeAt(i);return new Blob([arr],{type:mime})}
async function exportBackup(){toast("building scrapbook backup...");const media={};for(const k of await Media.keys()){const b=await Media.get(k);if(b)media[k]=await blobToDataURL(b)}const payload={app:"My Little Money Home",version:5,exported:new Date().toISOString(),state,media};const blob=new Blob([JSON.stringify(payload)],{type:"application/json"});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`moneyhome-backup-${todayISO()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast("backup saved 💾")}
async function importBackup(file){if(!file)return;try{const p=JSON.parse(await file.text());state=normalize(p.state||p);if(p.media)for(const [k,v] of Object.entries(p.media))await Media.put(dataURLToBlob(v),k);saveState();render();toast("little world restored ♡")}catch(e){console.error(e);toast("couldn't read that backup")}}

